describe("assignment while away", () => {
  it("assigns the delegate instead, in the stored row, the event and the alerts", async () => {
    const tenant = await createTenant("absence-assign");
    await markAway(tenant, tenant.userIds.member, tenant.userIds.viewer);
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Redirect me" }),
    );

    const seen: TaskflowEventMap["issue.assigned"][] = [];
    detachers.push(subscribe("issue.assigned", (payload) => void seen.push(payload)));

    const after = await issueService.assignIssue(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(after.assigneeId).toBe(tenant.userIds.viewer);
    expect(seen.map((payload) => payload.assigneeId)).toEqual([tenant.userIds.viewer]);
    expect(await alerts(tenant, tenant.userIds.viewer, "issue_assigned")).toHaveLength(1);
    expect(await alerts(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);
  });

  it("redirects an issue created with the away member as assignee", async () => {
    const tenant = await createTenant("absence-create");
    await markAway(tenant, tenant.userIds.member, tenant.userIds.admin);

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
