      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(after.assigneeId).toBe(tenant.userIds.member);
  });

  it("never chains delegation", async () => {
    const tenant = await createTenant("absence-chain");
    await markAway(tenant, tenant.userIds.member, tenant.userIds.admin);
    await markAway(tenant, tenant.userIds.admin, tenant.userIds.viewer);

    const issue = await issueService.createIssue(
      tenant.actors.owner,
