describe("membership changes", () => {
  it("drops a removed member's absence and a removed delegate's delegations", async () => {
    const tenant = await createTenant("absence-removal");
    await markAway(tenant, tenant.userIds.member, tenant.userIds.viewer);
    await markAway(tenant, tenant.userIds.viewer, tenant.userIds.admin);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    expect(await memberRepo.findAbsence(tenant.org.id, tenant.userIds.viewer)).toBeNull();
    const remaining = await memberService.getAbsence(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(remaining).not.toBeNull();
    expect(remaining?.delegateUserId).toBeNull();

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });
});

