/**
 * Out of office: setting, clearing and reading an absence, and how an active
 * one redirects assignments, overdue alerts and mention alerts to a delegate.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, UserId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const HOUR = 60 * 60 * 1000;

function at(offsetMs: number): IsoTimestamp {
  return new Date(Date.now() + offsetMs).toISOString() as IsoTimestamp;
}

/** Away from an hour ago until a day from now. */
async function markAway(
  tenant: Tenant,
  userId: UserId,
  delegateUserId: UserId | null,
): Promise<void> {
  await memberService.setAbsence(tenant.actors.owner, {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: at(-HOUR),
    endsAt: at(24 * HOUR),
    note: null,
  });
}

async function alerts(
  tenant: Tenant,
  recipientId: UserId,
  kind: NotificationKind,
) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("setAbsence / getAbsence / clearAbsence", () => {
  it("stores an absence and reads it back", async () => {
    const tenant = await createTenant("absence-roundtrip");
    const stored = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: at(HOUR),
      endsAt: at(2 * HOUR),
      note: "Conference",
    });

    expect(stored).toMatchObject({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      note: "Conference",
    });
    // A scheduled absence that has not started yet is still returned.
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(stored);
  });

  it("replaces the previous absence and can be cleared", async () => {
    const tenant = await createTenant("absence-replace");
    await markAway(tenant, tenant.userIds.member, tenant.userIds.admin);
    const replaced = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: at(-HOUR),
      endsAt: at(HOUR),
      note: null,
    });

    expect(replaced.delegateUserId).toBeNull();
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(replaced);

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("returns null once the absence has ended", async () => {
    const tenant = await createTenant("absence-ended");
    await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: at(-2 * HOUR),
      endsAt: at(-HOUR),
      note: null,
    });

    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("rejects an end that is not after the start", async () => {
    const tenant = await createTenant("absence-order");
    const startsAt = at(HOUR);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt,
        endsAt: startsAt,
        note: null,
      }),
    ).rejects.toThrow(/end after/);
  });

  it("rejects the member as their own delegate and unknown delegates", async () => {
    const tenant = await createTenant("absence-delegate");
    const other = await createTenant("absence-delegate-other");
    const base = {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      startsAt: at(-HOUR),
      endsAt: at(HOUR),
      note: null,
    };

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        ...base,
        delegateUserId: tenant.userIds.member,
      }),
    ).rejects.toThrow(/own delegate/);
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        ...base,
        delegateUserId: other.userIds.member,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("requires the member to be an active member of the organization", async () => {
    const tenant = await createTenant("absence-not-member");
