        orgId: tenant.org.id,
        userId: other.userIds.member,
        delegateUserId: null,
        startsAt: at(-HOUR),
        endsAt: at(HOUR),
        note: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets only role managers touch someone else's absence", async () => {
    const tenant = await createTenant("absence-permissions");

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.viewer,
        delegateUserId: null,
        startsAt: at(-HOUR),
        endsAt: at(HOUR),
        note: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await markAway(tenant, tenant.userIds.viewer, null);
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await memberService.clearAbsence(tenant.actors.admin, tenant.org.id, tenant.userIds.viewer);
  });

  it("refuses every operation on another organization", async () => {
    const tenant = await createTenant("absence-scope");
    const other = await createTenant("absence-scope-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, {
        orgId: other.org.id,
        userId: other.userIds.member,
        delegateUserId: null,
        startsAt: at(-HOUR),
        endsAt: at(HOUR),
        note: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

